String[] parseCsvLine(String line) {
    List<String> pola = new ArrayList<>();
    StringBuilder sb = new StringBuilder();
    boolean wCudzyslowie = false;
    for (int i = 0; i < line.length(); i++) {
        char c = line.charAt(i);
        if (c == '"') {
            if (wCudzyslowie && i+1 < line.length() && line.charAt(i+1) == '"') { sb.append('"'); i++; }
            else wCudzyslowie = !wCudzyslowie;
        } else if (c == ',' && !wCudzyslowie) { pola.add(sb.toString()); sb.setLength(0); }
        else sb.append(c);
    }
    pola.add(sb.toString());
    return pola.toArray(new String[0]);
}

